#include <iostream>
#include <queue>
#include <functional>
#include <chrono>
using namespace std;

class EventLoop {
    queue<function<void()>> queue;
    int time = 0;
    struct Event { int time; function<void()> cb; bool operator>(const Event& o) const { return time > o.time; } };
    priority_queue<Event, vector<Event>, greater<Event>> timers;
public:
    void post(function<void()> fn) { queue.push(fn); }

    void setTimeout(function<void()> fn, int delay) {
        timers.push({time + delay, fn});
    }

    void tick() {
        time++;
        while (!timers.empty() && timers.top().time <= time) {
            queue.push(timers.top().cb);
            timers.pop();
        }
    }

    void run(int steps) {
        for (int i = 0; i < steps; i++) {
            tick();
            if (!queue.empty()) { queue.front()(); queue.pop(); }
        }
    }
};

int main() {
    EventLoop loop;
    loop.setTimeout([]() { cout << "Timer 1 fired" << endl; }, 2);
    loop.setTimeout([]() { cout << "Timer 2 fired" << endl; }, 1);
    loop.post([]() { cout << "Immediate task" << endl; });
    loop.run(5);
    return 0;
}
